            for (; x; x /= 10) s += x % 10;
            return s;
        };
        int d = num / 10, r = num % 10;
        int ans = d > 0 ? 5 * d - 1 : 0;
        int want = dsum(d) % 2;
        int partial = want == 0 ? r / 2 + 1 : (r + 1) / 2;
        if (d == 0 && want == 0) partial--;
        return ans + partial;
