var countEven = function(num) {
    const dsum = x => {
        let s = 0;
        while (x > 0) {
            s += x % 10;
            x = Math.floor(x / 10);
        }
        return s;
    };
    const d = Math.floor(num / 10), r = num % 10;
    let ans = d > 0 ? 5 * d - 1 : 0;
    const want = dsum(d) % 2;
    let partial = want === 0 ? Math.floor(r / 2) + 1 : Math.floor((r + 1) / 2);
    if (d === 0 && want === 0) partial--;
    return ans + partial;
};
